def levelOrder_dfs(self, root) -> list[list[int]]:
    out: list[list[int]] = []

    def dfs(n, d):
        if not n:
            return
        if d == len(out):
            out.append([])
        out[d].append(n.val)
        dfs(n.left, d + 1)
        dfs(n.right, d + 1)

    dfs(root, 0)
    return out

